/* anim_retarget: one walk and one punch, made for one person, played on three
 * others with different proportions, rest poses, bone orientations and bone
 * names (cartwheel/retarget.h). Everyone is generated by make-characters.mjs.
 *
 *   Coach     1.74 m, plain bone names, T-pose: the only model with clips (a walk cycle and a punch)
 *   Runner    1.86 m, long legs, Mixamo bone names, T-pose. Its clips were baked by cwpack when the
 *             model was packed: models/runner.glb.cwimport names the coach as retarget.source
 *   Gymnast   1.58 m, short shins, VRM bone names, A-pose. Baked by cwpack too
 *   Lifter    1.78 m, broad, short legs, Unreal bone names, A-pose. Retargeted here at load, from C
 *
 * Each person is an instance of character.cwscene: a model, an AnimationPlayer and an AnimationTree
 * whose graph is text in the scene. The graph walks, and a one-shot layers the punch over the walk on
 * the spine and everything above it, so the legs keep walking while the arms punch. Everyone walks
 * across the floor at the speed their own legs make.
 *
 * The probe: while a foot is planted (near the floor in its own clip), its position in the world should
 * not move. slide_mm is the furthest any planted foot travelled over the ground during one stance, for the
 * three people and then the coach. The coach's own clip slides (its planted feet do not travel evenly);
 * the people's walk is retargeted with plant_feet, which takes the slide out, and must stay under 5 mm.
 * RETARGET_NO_FOOT_IK=1 (the gate's control) retargets every person at load without the foot pass;
 * RETARGET_NO_PLANT=1 keeps the foot pass and leaves the clip's own slide in.
 * RETARGET_SHEET=walk|attack|walk_side|attack_side stands the coach and the three people in a row, facing the
 * camera or side on, playing that one clip on the whole body: the views to judge a retarget by eye against
 * its source (knees, elbows, shoulders, hips).
 * RETARGET_CROWD=<n> adds n more lifters (cheap clones sharing the model and the clips), each with its
 * own tree, and times the trees: tree_us is microseconds per character per tick.
 * Debug fields: scale (leg ratio), speed, slide_mm, bake_diff (the cwpack bake against the clip made
 * here: the largest distance between the two for a foot, metres), feet_ok, stances, punches, hash_win. */
#include <math.h>
#include <stdio.h>
#include <stdlib.h>

#include "cartwheel/anim.h"
#include "cartwheel/debug.h"
#include "cartwheel/profile.h"
#include "cartwheel/resource.h"
#include "cartwheel/retarget.h"
#include "cartwheel/scene_file.h"

#define PEOPLE 3
#define X_MIN (-3.0f)
#define X_MAX 3.6f
#define SLIDE_BOUND_MM 5.0f /* the furthest a planted foot may travel over the ground during one stance */
#define COACH_SCALE 1.0f
#define MAX_CROWD 400
#define BAKE_FPS 60.0f /* keys per second in the retargeted clips (the .cwimport files say the same) */

typedef struct person {
  const char *name, *file;
  cw_node mover, model, anim, tree;
  cw_res res;
  t3_object *inst;
  cw_pose pose;
  cw_bone_map map;
  int foot[2];
  float plant_y[2]; /* a foot at or below this height (model space) is planted */
  float speed, drift, x, z0, scale; /* drift: the planted feet's sideways travel, taken out the same way */
  t3_vec3 last[2];
  bool planted[2];
  float run[2];     /* metres slid in the current stance */
} person;

/* the three people, then the coach (probed the same way: the clip's own slide) */
static person P[PEOPLE + 1] = { { "Runner", "runner" }, { "Gymnast", "gymnast" }, { "Lifter", "lifter" }, { "Coach", "coach" } };
static cw_node level, coach_mover, coach_model, coach_anim;
static cw_res coach_res;
static t3_object *coach_inst;
static cw_pose coach_pose;
static cw_bone_map coach_map;
static float coach_speed, coach_x;
static bool no_foot_ik, no_plant, started;
static int sheet; /* 0 off, 1 walk, 2 attack */

/* the crowd */
static cw_node crowd_tree[MAX_CROWD], crowd_mover[MAX_CROWD];
static t3_object *crowd_inst[MAX_CROWD];
static int32_t crowd;
static double tree_ns;
static int tree_n;

/* debug state */
static float scale[PEOPLE], speed[PEOPLE + 1], slide_mm[PEOPLE + 1], bake_diff, tree_us, tree_us_min = 1e9f;
static int32_t feet_ok, punches, stances;
static uint32_t hash_win[8];

static void set_shadows(t3_object *o) {
  if (o->type == T3_SKINNED_MESH || o->type == T3_MESH) o->cast_shadow = true;
  for (int i = 0; i < o->child_count; i++) set_shadows(o->children[i]);
}

/* #region maps */
/* the coach's bones from their names, and the two the names do not give (its hands are called Grip) */
static void coach_bones(void) {
  cw_pose_bind(&coach_pose, coach_inst);
  cw_bone_map_auto(&coach_map, &coach_pose);
  cw_bone_map_apply_text(&coach_map, &coach_pose,
                         "left_hand = GripL\n"
                         "right_hand = GripR\n");
}
/* #endregion */

/* a clip of the model's own glTF by name */
static cw_anim gltf_clip(cw_res res, const char *name, const char *model_path) {
  const cw_gltf *g = cw_res_gltf(res);
  for (int i = 0; g && i < g->gltf->animation_count; i++)
    if (!strcmp(g->gltf->animations[i]->name, name)) return cw_anim_from_t3_clip(g->gltf->animations[i], model_path);
  return (cw_anim){ 0 };
}

/* A clip's pose at `time` in a pose (no nodes involved): rest, then every bone track. */
static void pose_at(cw_anim a, cw_pose *p, float time) {
  for (int i = 0; i < p->count; i++) { p->pos[i] = p->rest_pos[i]; p->rot[i] = p->rest_rot[i]; p->scl[i] = p->rest_scl[i]; }
  for (int t = 0; t < cw_anim_track_count(a); t++) {
    const char *path = cw_anim_track_path(a, t), *at = strchr(path, '@'), *colon = strrchr(path, ':');
    if (!at || !colon) continue;
    char bone[128];
    snprintf(bone, sizeof bone, "%.*s", (int)(colon - at - 1), at + 1);
    int b = cw_pose_find(p, bone);
    cw_value v;
    if (b < 0 || !cw_anim_sample(a, t, time, &v)) continue;
    if (!strcmp(colon + 1, "quaternion")) p->rot[b] = (t3_quat){ v.v[0], v.v[1], v.v[2], v.v[3] };
    else if (!strcmp(colon + 1, "position")) p->pos[b] = (t3_vec3){ v.v[0], v.v[1], v.v[2] };
  }
  cw_pose_update_model(p);
}

/* The height under which a foot counts as planted in a walk clip (the lowest tenth of its travel, as
 * cw_foot_plant counts it). */
static void plant_heights(cw_anim walk, cw_pose *p, const int foot[2], float plant_y[2]) {
  float len = cw_anim_length(walk), lo[2] = { 1e9f, 1e9f }, hi[2] = { -1e9f, -1e9f };
  for (int k = 0; k <= 120; k++) {
    pose_at(walk, p, len * (float)k / 120);
    for (int f = 0; f < 2; f++) {
      float y = cw_pose_model_position(p, foot[f]).y;
      lo[f] = fminf(lo[f], y);
      hi[f] = fmaxf(hi[f], y);
    }
  }
  for (int f = 0; f < 2; f++) plant_y[f] = lo[f] + 0.05f * (hi[f] - lo[f]); /* well inside what cw_foot_plant counts (0.1) */
  pose_at(walk, p, 0);
}

static void start(void) {
  started = true;
  const char *env = cw_test_env("RETARGET_NO_FOOT_IK");
  no_foot_ik = env && env[0] == '1';
  env = cw_test_env("RETARGET_NO_PLANT");
  no_plant = env && env[0] == '1';
  cw_res_wait_all();
  coach_inst = cw_gltf_instantiate(coach_res);
  if (!coach_inst) { cw_error("anim_retarget: models/coach.glb did not load"); return; }
  cw_node3d_set_object(coach_model, coach_inst);
  set_shadows(coach_inst);
  coach_bones();
  cw_anim swalk = gltf_clip(coach_res, "Walk", "Model"), spunch = gltf_clip(coach_res, "Punch", "Model");
  cw_anim_set_loop(swalk, CW_LOOP_LINEAR);
  cw_anim_player_add(coach_anim, "walk", swalk);
  int sfoot[2] = { coach_map.bone[CW_HB_LEFT_FOOT], coach_map.bone[CW_HB_RIGHT_FOOT] };
  float splant[2];
  plant_heights(swalk, &coach_pose, sfoot, splant);
  /* #region speed */
  /* walk at the speed the clip's planted feet travel backwards (everyone faces +z in their model) */
  coach_speed = -cw_anim_ground_velocity(swalk, &coach_pose, sfoot[0], sfoot[1], true).z * COACH_SCALE;
  /* #endregion */
  speed[PEOPLE] = coach_speed;
  person *rb = &P[PEOPLE];
  rb->mover = coach_mover;
  cw_pose_bind(&rb->pose, coach_inst);
  rb->foot[0] = sfoot[0]; rb->foot[1] = sfoot[1];
  rb->plant_y[0] = splant[0]; rb->plant_y[1] = splant[1];
  rb->scale = COACH_SCALE;
  cw_anim_player_play(coach_anim, "walk", 0);

  cw_retarget_opts opts = CW_RETARGET_OPTS_DEFAULT;
  opts.foot_ik = !no_foot_ik;
  opts.fps = BAKE_FPS;
  for (int i = 0; i < PEOPLE; i++) {
    person *q = &P[i];
    q->inst = cw_gltf_instantiate(q->res);
    if (!q->inst) { cw_error("anim_retarget: models/%s.glb did not load", q->file); return; }
    cw_node3d_set_object(q->model, q->inst);
    set_shadows(q->inst);
    cw_pose_bind(&q->pose, q->inst);
    cw_bone_map_auto(&q->map, &q->pose);
    q->foot[0] = q->map.bone[CW_HB_LEFT_FOOT];
    q->foot[1] = q->map.bone[CW_HB_RIGHT_FOOT];
    /* #region load */
    /* the clips: baked into the model by cwpack (walk, attack), or made here from the coach's */
    cw_anim walk = gltf_clip(q->res, "walk", "Model"), attack = gltf_clip(q->res, "attack", "Model");
    bool baked = cw_anim_valid(walk);
    cw_retarget_opts wopts = opts; /* the walk repeats, and its planted feet get their slide taken out */
    wopts.plant_feet = !no_plant;
    wopts.cyclic = true;
    cw_anim cwalk = cw_retarget_clip(swalk, &coach_pose, &coach_map, &q->pose, &q->map, "Model", &wopts);
    if (!baked || no_foot_ik || no_plant) {
      cw_anim_release(walk);
      cw_anim_release(attack);
      walk = cwalk;
      cw_anim_retain(walk);
      attack = cw_retarget_clip(spunch, &coach_pose, &coach_map, &q->pose, &q->map, "Model", &opts);
    }
    /* #endregion */
    cw_retarget *rt = cw_retarget_new(&coach_pose, &coach_map, &q->pose, &q->map, &opts);
    q->scale = scale[i] = cw_retarget_scale(rt);
    /* the bake in the pack and the clip made here are the same motion: the largest difference in a
     * foot's model position over the walk */
    if (baked && !no_foot_ik && !no_plant) {
      float len = cw_anim_length(walk);
      for (int k = 0; (float)k / BAKE_FPS <= len; k++) {
        t3_vec3 a[2], b[2];
        pose_at(walk, &q->pose, (float)k / BAKE_FPS);
        for (int f = 0; f < 2; f++) a[f] = cw_pose_model_position(&q->pose, q->foot[f]);
        pose_at(cwalk, &q->pose, (float)k / BAKE_FPS);
        for (int f = 0; f < 2; f++) {
          b[f] = cw_pose_model_position(&q->pose, q->foot[f]);
          bake_diff = fmaxf(bake_diff, sqrtf((a[f].x - b[f].x) * (a[f].x - b[f].x) + (a[f].y - b[f].y) * (a[f].y - b[f].y) + (a[f].z - b[f].z) * (a[f].z - b[f].z)));
        }
      }
    }
    cw_anim_release(cwalk);
    cw_anim_set_loop(walk, CW_LOOP_LINEAR);
    plant_heights(walk, &q->pose, q->foot, q->plant_y);
    t3_vec3 gv = cw_anim_ground_velocity(walk, &q->pose, q->foot[0], q->foot[1], true);
    q->speed = speed[i] = -gv.z;
    q->drift = gv.x;
    q->z0 = cw_node3d_position(q->mover).z;
    cw_anim_player_add(q->anim, "walk", walk);
    cw_anim_player_add(q->anim, "attack", attack);
    cw_anim_release(walk);
    cw_anim_release(attack);
    q->x = X_MIN;
  }
  cw_anim spunch2 = spunch; /* the sheet shows the coach punching too */
  cw_anim_release(swalk);

  /* the contact sheet: everyone on the spot in a row, the coach first, facing the camera or side on */
  const char *sh = cw_test_env("RETARGET_SHEET");
  sheet = !sh ? 0 : !strncmp(sh, "attack", 6) ? 2 : !strncmp(sh, "walk", 4) ? 1 : 0;
  if (sheet) {
    bool side = strstr(sh, "side") != NULL;
    float yaw = side ? 1.5707963f : 0;
    const char *graph = sheet == 2 ? "clip name=\"a\" anim=\"attack\"\n" : "clip name=\"a\" anim=\"walk\"\n";
    cw_node cam = cw_node_get(level, "Camera");
    cw_node3d_set_position(cam, (t3_vec3){ 0, 1.05f, 9.5f });
    cw_node3d_set_rotation(cam, (t3_vec3){ -0.015f, 0, 0 });
    cw_node_set(cam, "fov", cw_val_float(22));
    cw_anim_player_add(coach_anim, "attack", spunch2);
    cw_anim_set_loop(spunch2, CW_LOOP_LINEAR);
    cw_anim_player_play(coach_anim, sheet == 2 ? "attack" : "walk", 0);
    cw_node3d_set_position(coach_mover, (t3_vec3){ -2.25f, 0, 0 });
    cw_node3d_set_rotation(coach_mover, (t3_vec3){ 0, yaw, 0 });
    for (int i = 0; i < PEOPLE; i++) {
      person *q = &P[i];
      cw_anim_set_loop(cw_anim_player_get(q->anim, "attack"), CW_LOOP_LINEAR);
      cw_animtree_load_text(q->tree, graph);
      cw_node3d_set_position(q->mover, (t3_vec3){ -0.75f + 1.5f * (float)i, 0, 0 });
      cw_node3d_set_rotation(q->mover, (t3_vec3){ 0, yaw, 0 });
    }
  }
  cw_anim_release(spunch2);

  /* a crowd of lifters: the same model resource, the same two clips, a tree each */
  const char *cn = cw_test_env("RETARGET_CROWD");
  crowd = cn ? atoi(cn) : 0;
  if (crowd > MAX_CROWD) crowd = MAX_CROWD;
  person *l = &P[2];
  for (int i = 0; i < crowd; i++) {
    char name[32];
    snprintf(name, sizeof name, "Crowd%d", i);
    cw_node c = cw_scene_instance_path("character.cwscene");
    cw_node_set_name(c, name);
    cw_node_add_child(level, c);
    crowd_mover[i] = c;
    crowd_tree[i] = cw_node_get(c, "Tree");
    crowd_inst[i] = cw_gltf_instantiate(l->res);
    cw_node3d_set_object(cw_node_get(c, "Model"), crowd_inst[i]);
    cw_animtree_load_text(crowd_tree[i], "clip name=\"walk\" anim=\"walk\"\nclip name=\"attack\" anim=\"attack\"\n"
                                         "oneshot name=\"top\" base=\"walk\" shot=\"attack\" param=\"attack\" fadein=0.12 fadeout=0.25 bones=\"spine_01+\"\n");
    cw_node_set(crowd_tree[i], "process", cw_val_int(CW_ANIM_PROCESS_MANUAL)); /* advanced below, inside the timer */
    cw_anim_player_add(cw_node_get(c, "Anim"), "walk", cw_anim_player_get(l->anim, "walk"));
    cw_anim_player_add(cw_node_get(c, "Anim"), "attack", cw_anim_player_get(l->anim, "attack"));
    cw_node3d_set_position(c, (t3_vec3){ -9.0f + 1.0f * (float)(i % 20), 0, -4.0f - 1.2f * (float)(i / 20) });
  }
}

static void init(void *u) {
  (void)u;
  level = cw_node_get(cw_tree_root(cw_scene_app_tree()), "Level");
  coach_mover = cw_node_get(level, "Coach");
  coach_model = cw_node_get(coach_mover, "Model");
  coach_anim = cw_node_get(coach_mover, "Anim");
  coach_res = cw_res_load_async("res://models/coach.glb", 0, NULL, NULL);
  for (int i = 0; i < PEOPLE; i++) {
    char path[64];
    person *q = &P[i];
    q->mover = cw_node_get(level, q->name);
    q->model = cw_node_get(q->mover, "Model");
    q->anim = cw_node_get(q->mover, "Anim");
    q->tree = cw_node_get(q->mover, "Tree");
    snprintf(path, sizeof path, "res://models/%s.glb", q->file);
    q->res = cw_res_load_async(path, 0, NULL, NULL);
  }
  cw_debug_f32_array("scale", scale, PEOPLE);
  cw_debug_f32_array("speed", speed, PEOPLE + 1);
  cw_debug_f32_array("slide_mm", slide_mm, PEOPLE + 1);
  cw_debug_f32("bake_diff", &bake_diff);
  cw_debug_i32("feet_ok", &feet_ok);
  cw_debug_i32("stances", &stances);
  cw_debug_i32("punches", &punches);
  cw_debug_i32("crowd", &crowd);
  cw_debug_field("hash_win", hash_win, CW_DBG_U32, 8);
  cw_debug_f32("tree_us", &tree_us);         /* host clock: never compared */
  cw_debug_f32("tree_us_min", &tree_us_min); /* the quietest tick */
}

/* #region probe */
/* a planted foot must stay where it is in the world: how far it travels during one stance */
static void probe(person *q, int i, float x, float draw_scale) {
  cw_pose_capture(&q->pose);
  for (int f = 0; f < 2; f++) {
    t3_vec3 m = cw_pose_model_position(&q->pose, q->foot[f]);
    /* the model faces +x (yaw 90 degrees): model z runs along world x */
    t3_vec3 w = { x + m.z * draw_scale, m.y * draw_scale, cw_node3d_position(q->mover).z - m.x * draw_scale };
    bool planted = m.y <= q->plant_y[f];
    if (planted && q->planted[f]) {
      q->run[f] += sqrtf((w.x - q->last[f].x) * (w.x - q->last[f].x) + (w.z - q->last[f].z) * (w.z - q->last[f].z));
      if (q->run[f] * 1000 > slide_mm[i]) slide_mm[i] = q->run[f] * 1000;
    } else if (planted) {
      q->run[f] = 0;
      if (i < PEOPLE) stances++;
    }
    q->planted[f] = planted;
    q->last[f] = w;
  }
}
/* #endregion */

static void fixed_update(void *u, double dt) {
  (void)u;
  uint64_t tick = cw_tick_index();
  if (tick < 2) return; /* a gate's switches arrive with frame 2 */
  if (!started) start();
  if (!coach_inst || sheet) return;
  coach_x += coach_speed * (float)dt;
  if (coach_x > X_MAX - X_MIN) { coach_x = 0; P[PEOPLE].planted[0] = P[PEOPLE].planted[1] = false; }
  if (tick > 4) probe(&P[PEOPLE], PEOPLE, X_MIN + coach_x, COACH_SCALE);
  cw_node3d_set_position(coach_mover, (t3_vec3){ X_MIN + coach_x, 0, cw_node3d_position(coach_mover).z });
  cw_node3d_set_rotation(coach_mover, (t3_vec3){ 0, 1.5707963f, 0 });
  for (int i = 0; i < PEOPLE; i++) {
    person *q = &P[i];
    if (!q->inst) continue;
    bool wrapped = false;
    q->x += q->speed * (float)dt;
    float z = cw_node3d_position(q->mover).z + q->drift * (float)dt; /* model x runs along world -z */
    if (q->x > X_MAX) { q->x = X_MIN; z = q->z0; wrapped = true; }
    cw_node3d_set_position(q->mover, (t3_vec3){ q->x, 0, z });
    cw_node3d_set_rotation(q->mover, (t3_vec3){ 0, 1.5707963f, 0 });
    if (wrapped) cw_node3d_snapshot(q->mover), q->planted[0] = q->planted[1] = false;
    /* #region punch */
    /* one set of the parameter is one punch, layered over the walk on the spine and above */
    if (tick % 150 == (uint64_t)(40 + 30 * i)) {
      cw_animtree_set_param(q->tree, "attack", 1);
      punches++;
    }
    /* #endregion */
    if (tick > 4) probe(q, i, q->x, 1);
    if (tick / 60 < 8) hash_win[tick / 60] = cw_hash32(&(uint32_t){ cw_animtree_hash(q->tree) }, 4, hash_win[tick / 60] ? hash_win[tick / 60] : CW_HASH32_INIT);
  }
  feet_ok = stances >= 6;
  for (int i = 0; i < PEOPLE; i++) feet_ok = feet_ok && slide_mm[i] <= SLIDE_BOUND_MM;
  feet_ok = feet_ok && (no_foot_ik || no_plant || bake_diff < 1e-5f);
  if (crowd) {
    uint64_t t0 = cw_profile_now_ns();
    for (int i = 0; i < crowd; i++) {
      if ((tick + (uint64_t)i * 7) % 150 == 0) cw_animtree_set_param(crowd_tree[i], "attack", 1);
      cw_animtree_advance(crowd_tree[i], dt);
    }
    double ns = (double)(cw_profile_now_ns() - t0);
    tree_ns += ns;
    tree_n++;
    tree_us = (float)(tree_ns / tree_n / 1000.0 / crowd);
    if (tick > 30 && (float)(ns / 1000.0 / crowd) < tree_us_min) tree_us_min = (float)(ns / 1000.0 / crowd);
  }
}

static void shutdown(void *u) {
  (void)u;
  cw_pose_free(&P[PEOPLE].pose);
  for (int i = 0; i < PEOPLE; i++) {
    cw_pose_free(&P[i].pose);
    if (P[i].inst) t3_release(P[i].inst);
  }
  for (int i = 0; i < crowd; i++)
    if (crowd_inst[i]) t3_release(crowd_inst[i]);
  cw_pose_free(&coach_pose);
  if (coach_inst) t3_release(coach_inst);
}

cw_app_desc cw_main(int argc, char **argv) {
  (void)argc; (void)argv;
  static cw_app_desc app = { .title = "anim_retarget", .width = 1280, .height = 720, .debug = true,
                             .init = init, .fixed_update = fixed_update, .shutdown = shutdown };
  return cw_scene_app("main.cwscene", &app);
}
